# Problem: two-sum returning indices.
# Hash map of value->index for O(n) lookup.
def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []
```

