# Problem: longest consecutive equal-element run length.
# Track current run; bump or reset.
def longest_run(lst):
    if not lst:
        return 0
    best = current = 1
    for i in range(1, len(lst)):
        if lst[i] == lst[i - 1]:
            current += 1
            best = max(best, current)
        else:
            current = 1
    return best
```

